begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
select hasnt_table('public','events','planned events are retired');
select hasnt_table('public','tasks','calendar tasks are retired');
select hasnt_view('public','calendar_entries','calendar projection is retired');
select hasnt_table('public','schedule_push_deliveries','morning delivery queue and history are retired');
select hasnt_table('public','community_posts','legacy public boards are retired');
select hasnt_table('public','community_comments','legacy board comments are retired');
select hasnt_table('public','community_photos','legacy board photo metadata is retired');
select hasnt_table('public','community_boards','legacy country board catalog is retired');
select hasnt_column('public','residence_regions','community_scope','legacy board grouping metadata is retired');
select hasnt_table('public','parenting_post_announcements','country announcements are retired');
select has_table('public','neighborhood_posts','neighborhood conversations remain');
select has_table('public','community_reports','neighborhood and diary moderation remain');
select has_table('public','community_photo_cleanup','shared storage cleanup queue remains');
select has_table('public','care_records','actual feeding records remain');
select has_table('public','child_records','actual care and health records remain');
select has_column('public','vaccination_records','completed_date','vaccination completions remain');
select hasnt_column('public','vaccination_records','status','vaccinations have no planning status');
select hasnt_column('public','vaccination_records','scheduled_date','vaccinations have no planning date');
select col_not_null('public','vaccination_records','completed_date','vaccinations require an actual completion date');
select hasnt_column('public','notification_preferences','task_enabled','task preference is retired');
select hasnt_column('public','notification_preferences','event_enabled','event preference is retired');
select hasnt_column('public','notification_preferences','delivery_hour','calendar delivery clock is retired');
select hasnt_column('public','notification_preferences','schedule_enabled','morning schedule preference is retired');
select hasnt_column('public','notification_preferences','schedule_enabled_at','morning activation timestamp is retired');
select has_column('public','notification_preferences','frequency_minutes','feeding inbox throttle remains');
select ok(to_regprocedure('public.save_push_settings(text,integer,boolean,boolean,boolean,jsonb,text)') is not null,'push settings expose seven retained inputs');
select ok(to_regprocedure('public.save_push_settings(text,integer,boolean,boolean,boolean,jsonb,text,boolean)') is null,'old schedule settings overload is absent');
select ok(to_regprocedure('public.save_notification_preferences(boolean,boolean,boolean,time,time,integer,integer,integer,integer)') is null,'legacy mixed preferences API is absent');
select ok(to_regprocedure('public.delete_calendar_item(uuid,text)') is null,'calendar deletion API is absent');
select is((select count(*) from pg_catalog.pg_proc p join pg_catalog.pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname='delete_calendar_item'),0::bigint,'calendar deletion has no remaining overloads');
select ok(to_regprocedure('public.schedule_items(uuid,date)') is null,'schedule read API is absent');
select ok(to_regprocedure('public.claim_schedule_push(text)') is null,'schedule worker API is absent');
select ok(to_regprocedure('public.parenting_feed(uuid,boolean,text,timestamptz,uuid,text,bigint,text)') is null,'country selector feed overload is absent');
select ok(to_regprocedure('public.parenting_feed(uuid,text,timestamptz,uuid,text,bigint,text)') is not null,'neighborhood feed remains');
select ok(to_regprocedure('public.save_parenting_post(uuid,text,text,text,uuid,uuid[],uuid,jsonb,text)') is null,'audience selector writer overload is absent');
select ok(to_regprocedure('public.save_parenting_post(uuid,text,text,text,uuid,uuid[],uuid,jsonb)') is not null,'neighborhood writer remains');
select is((select count(*) from neighborhood_posts where audience<>'neighborhood'),0::bigint,'no retired country posts remain');
select is((select count(*) from notifications where kind<>'feeding'),0::bigint,'inbox contains only feeding reminders');
select ok(pg_get_functiondef('public.dispatch_feeding_push()'::regprocedure) not like '%schedule_push%','shared worker dispatch has no schedule branch');
select ok(pg_get_functiondef('public.export_child_data(uuid)'::regprocedure) not like '%public.tasks%','exports have no retired tasks');
select ok(pg_get_functiondef('public.export_child_data(uuid)'::regprocedure) not like '%public.events%','exports have no retired events');
select ok(pg_get_functiondef('public.revoke_member(uuid,uuid)'::regprocedure) not like '%public.tasks%','caregiver revocation has no retired assignment write');
select ok(pg_get_functiondef('public.update_health_consent(boolean,text)'::regprocedure) not like '%public.events%','health withdrawal has no retired event write');
select * from finish();
rollback;
